import java.sql.*; public class DbCheck { public static void main(String[] args) { try { Connection conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/ncp_com_db?serverTimezone=UTC", "root", ""); Statement stmt = conn.createStatement(); ResultSet rs = stmt.executeQuery("SELECT username, role FROM users"); while (rs.next()) { System.out.println(rs.getString("username") + ": " + rs.getString("role")); } } catch(Exception e) { e.printStackTrace(); } } }
